/**
 * registerSW.ts — registers the service worker generated by vite-plugin-pwa (vite.config.ts).
 *
 * The service worker caches the whole app so it opens offline. With `registerType: 'autoUpdate'`
 * a new deploy is downloaded in the background and activated automatically; we also check for
 * updates every hour while the app is open, so long-running sessions pick up fixes.
 * Troubleshooting stale versions: docs/TROUBLESHOOTING.md → "The app shows an old version".
 */
import { registerSW } from 'virtual:pwa-register'

/** Registers the service worker (no-op in dev and in browsers without support). */
export function registerServiceWorker(): void {
  if (!('serviceWorker' in navigator) || import.meta.env.DEV) return
  registerSW({
    immediate: true,
    onRegisteredSW(_url, registration) {
      if (!registration) return
      setInterval(() => void registration.update(), 60 * 60 * 1000)
    },
  })
}
